set local role authenticated;
select set_config('request.jwt.claim.sub','92222222-2222-4222-8222-222222222222',true);
do $$ declare category uuid;home uuid;wallet uuid;body jsonb;req uuid:=gen_random_uuid();result jsonb;balance numeric;row public.spending_categories;
begin
 select category_id into category from public.get_spending_categories() where name='Business';
 select category_id into home from public.get_spending_categories() where name='Home';
 select wallet_id into wallet from public.wallets where type='cash';
 select w.balance into balance from public.wallets w where wallet_id=wallet;
 body:=jsonb_build_object('category_id',category,'category_name','Business','classification','cost','wallet_id',wallet,'amount',100,'spending_date',(now() at time zone 'Asia/Dhaka')::date,'description','SQL supplies');
 result:=public.record_spending(body,req);
 perform pg_temp.employee_assert(public.record_spending(body,req)=result,'spending exact once');
 perform pg_temp.employee_reject(format('select public.record_spending(%L,%L)',body||'{"amount":101}',req),'different details');
 perform pg_temp.employee_reject(format('select public.record_spending(%L,%L)',body||'{"amount":0}',gen_random_uuid()),'positive');
 perform pg_temp.employee_reject(format('select public.record_spending(%L,%L)',body||'{"amount":1.001}',gen_random_uuid()),'decimal');
 perform public.record_spending(body||jsonb_build_object('category_id',home,'category_name','Home','classification','withdrawal','amount',50),gen_random_uuid());
 perform pg_temp.employee_assert((public.get_spendings()->>'costs')::numeric=100 and (public.get_spendings()->>'withdrawals')::numeric=50,'cost and withdrawal totals');
 perform pg_temp.employee_assert((select w.balance from public.wallets w where wallet_id=wallet)=balance-150,'only the ledger deducts spending');
 select * into row from public.get_spending_categories() where category_id=category;
 perform public.save_spending_category(to_jsonb(row)||'{"name":"Supplies renamed","classification":"withdrawal"}');
 perform pg_temp.employee_assert((public.get_spendings()->>'costs')::numeric=100,'historical classification snapshot');
 perform pg_temp.employee_reject(format('select public.record_spending(%L,%L)',body,gen_random_uuid()),'Category changed');
 perform pg_temp.employee_reject(format('select public.save_spending_category(%L)',to_jsonb(row)),'Category changed');
 perform public.save_spending_category('{"name":"Travel","classification":"cost"}');
 perform pg_temp.employee_assert((public.get_spendings('{"classification":"withdrawal"}',0,1)->>'total')::integer=1,'server filtering and pagination');
 perform pg_temp.employee_assert(not exists(select 1 from public.get_vehicle_crew_options('Driver') d join public.get_vehicle_crew_options('Helper') h using(employee_id)),'role-specific options');
 perform set_config('request.jwt.claim.sub','82222222-2222-4222-8222-222222222222',true);
 perform pg_temp.employee_assert((public.get_spendings()->>'total')::int=0,'foreign spending history isolated');
 perform pg_temp.employee_reject(format('select public.record_spending(%L,%L)',body,gen_random_uuid()),'category');
end $$;
reset role;
select pg_temp.employee_assert(not has_table_privilege('authenticated','public.spendings','insert') and not has_function_privilege('anon','public.record_spending(jsonb,uuid)','execute'),'spending mutation boundaries');
select 'PASS: costs/withdrawals, canonical ledger reconciliation, category snapshots/revisions, idempotency, validation, paging and tenant isolation';
